import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"7、【师】 坎下坤上","description":"周易尚氏学 - 7、【师】 坎下坤上","frontmatter":{"title":"7、【师】 坎下坤上","description":"周易尚氏学 - 7、【师】 坎下坤上"},"headers":[],"relativePath":"zh/classics/shangshi/012.md","filePath":"zh/classics/shangshi/012.md"}'),h={name:"zh/classics/shangshi/012.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_7、【师】-坎下坤上" tabindex="-1">7、【师】 坎下坤上 <a class="header-anchor" href="#_7、【师】-坎下坤上" aria-label="Permalink to “7、【师】 坎下坤上”">​</a></h1><p>师。众也。坤舍于坎。俱居子方。坤坎皆为众。故曰师。犹乾舍于离。俱居午为同人也。贞。卜问也。大人。正义作丈人。子夏传作大人。崔憬李鼎祚从之是也。此与困贞大人吉同。皆谓二。乾九二云。利见大人。利见故吉。陆绩郑王等皆读为丈。谓震为长子。丈者长也。故曰丈人。岂知二得中。临御万民。大人之事。以二为大人。于象方合。丈人则于卦名不类矣。陆谓丈人为圣人。王谓丈人为庄严之称。皆曲说也。且子夏传为韩婴所作。(臧庸据七略。谓婴字子夏。今按艺文志有韩氏二篇。注曰名婴。其篇数与隋唐志子夏传卷数同。疑即子夏传。)与田何同时。皆秦遗老。其所据当无误也。</p><p>象曰。师众也。贞正也。能以众正。可以王矣。刚中而应。行险而顺。以此毒天下而民从之。吉又何咎矣。</p><p>震为帝为王。故曰可以王。二应五。坎险坤顺。震为行。故曰行险而顺。易林以坤为害。坎为毒。震为从。乾宝云。毒荼苦也。按列子宋阳里华子病忘。阖室毒之。注毒苦也。师旅之兴。不无所苦。然非师旅不能安天下。故民从之而吉也。吴语云。吾先君阖庐，以与楚昭王毒逐于中原柏举。义与此同也。马融训毒为治。与行险而顺。义不相应。行险即毒。顺即民从也。他若王弼之训毒为役。崔憬训为亭毒。俞樾训为督。皆不协。是皆因坎毒之象。人不尽知。故众说纷纭也。岂知噬嗑六三云。遇毒。以坎为毒。象甚明也。</p><p>象曰。地中有水。师。君子以容民畜众。</p><p>地中所容畜。莫多于水。故君子法之。</p><p>初六。师出以律。否臧凶。</p><p>坎为律。律法也。臧善也。否臧。即失律也。失律故凶。</p><h3 id="象曰。师出以律。失律凶也。" tabindex="-1">象曰。师出以律。失律凶也。 <a class="header-anchor" href="#象曰。师出以律。失律凶也。" aria-label="Permalink to “象曰。师出以律。失律凶也。”">​</a></h3><p>坎为失。故曰失律。</p><p>九二。在师中吉。无咎。王三锡命。</p><p>居下卦之中。故曰在师中吉。失位宜有咎。在师中。故无咎。震为王为言。故曰命。震数三。锡予也。王三锡命者。言王以官爵或车服器物。锡予有功。而告命之也。曲礼一命受爵。二命受服。三命受车马。言二为卦主。抚驭万邦。而日有所锡予也。旧解谓六五为君。锡命于二。于卦义全背。祇荀爽谓王指二为得解。</p><h3 id="象曰。在师中吉。承天宠也。王三锡命。怀万邦也。" tabindex="-1">象曰。在师中吉。承天宠也。王三锡命。怀万邦也。 <a class="header-anchor" href="#象曰。在师中吉。承天宠也。王三锡命。怀万邦也。" aria-label="Permalink to “象曰。在师中吉。承天宠也。王三锡命。怀万邦也。”">​</a></h3><p>五天位。言二必升五。为群阴所承也。故曰承天宠。坤为万邦。言二临万邦。而有所锡予者。正所以怀念万邦。坎为怀也。故夫旧解谓六五锡二者。不惟于经背。于象传亦背矣。</p><p>六三。师或舆尸。凶。坎为尸。</p><p>震为舆。管辂以坎为棺椁。故曰舆尸。夫陈师而出。。舆尸以还。其无功甚矣。故曰凶。盖坤为死。三失位无应。以阴遇阴。得敌。故凶如是。</p><h3 id="象曰。师或舆尸。大无功也。" tabindex="-1">象曰。师或舆尸。大无功也。 <a class="header-anchor" href="#象曰。师或舆尸。大无功也。" aria-label="Permalink to “象曰。师或舆尸。大无功也。”">​</a></h3><p>大无功。即太无功。</p><p>六四。师左次。无咎。</p><p>次舍也。震为左。故曰左次。古人尚右。左次则退也。四前临重阴。阴遇阴得敌。其行难矣。知难而退。故无咎也。</p><h3 id="象曰。左次无咎。未失常也。" tabindex="-1">象曰。左次无咎。未失常也。 <a class="header-anchor" href="#象曰。左次无咎。未失常也。" aria-label="Permalink to “象曰。左次无咎。未失常也。”">​</a></h3><p>未失常者。言四当位。量力自处。故不改其常。</p><p>六五。田有禽。利执言。无咎。长子帅师。弟子舆尸。贞凶。</p><p>田猎。禽获也。释文云。徐本作擒。王陶庐云。说文无擒字。其见于经传者。皆作禽。展获字禽。不从手。是其证。下应二阳故有禽获。二震为言。利执言者。言师出有名。如汤武历数桀纣之罪。汉高讨杀怀王者是也。故无咎。五应二。二震主爻。震长子。居师中为主。故曰长子帅师。二亦坎主爻。坎为震弟为尸。故曰弟子舆尸。舆尸故贞凶。贞卜问也。言五宜与震。不宜与坎。与坎。则使不当矣。</p><h3 id="象曰。长子帅师。以中行也。弟子舆尸。使不当也。" tabindex="-1">象曰。长子帅师。以中行也。弟子舆尸。使不当也。 <a class="header-anchor" href="#象曰。长子帅师。以中行也。弟子舆尸。使不当也。" aria-label="Permalink to “象曰。长子帅师。以中行也。弟子舆尸。使不当也。”">​</a></h3><p>二居中为震主。故为群阴之帅。二坎陷于阴中。不可使。使则有舆尸之祸也。宋衷虞翻谓弟子指六三。非是。皆因三爻有舆尸字而误。</p><p>上六。大君有命。开国承家。小人勿用。</p><p>大君指二震。震为君为言。故曰大君有命。坤为国。二升五居坤中。故曰开国。坎为室为家。二升五仍坎体。群阴承之。故曰承家。小人指上六。二升五虽开国承家。上六独居五后。乘阳势逆。不顺承五。比之后夫凶。即此爻也。故戒曰勿用。宋衷虞翻解开国承家是矣。然二升五于上六何涉。即以勿用为戒。必有故也。不申其故。只以坤为小人。笼统说之。胡可乎。惠栋知其不安。仍不能得其故。竟谓小人指初三。益淆乱矣。</p><h3 id="象曰。大君有命。以正功也。小人勿用。必乱邦也。" tabindex="-1">象曰。大君有命。以正功也。小人勿用。必乱邦也。 <a class="header-anchor" href="#象曰。大君有命。以正功也。小人勿用。必乱邦也。" aria-label="Permalink to “象曰。大君有命。以正功也。小人勿用。必乱邦也。”">​</a></h3><p>二升五位正。故曰正功。坤为邦为乱。上六反君道。故曰必乱邦。</p>',30)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
